local FL=#field
local function B(i) return (string.byte(field,1+(i%FL))-33)/89 end
local sky={{7,17,48},{9,25,63},{13,35,79},{20,47,94},{32,61,105},{51,78,113},{76,94,119},{105,111,126},{137,121,131},{170,126,127},{200,130,116},{224,138,104},{240,151,105},{248,169,119}}
local sea={{7,27,45},{8,35,55},{9,44,66},{10,53,76},{12,62,84},{15,70,91},{19,78,97},{24,85,102},{30,91,106},{37,97,109},{45,102,110},{54,107,109},{64,111,106},{76,115,102}}
local warm={{255,98,42},{255,117,48},{255,137,58},{255,158,72},{255,180,94},{255,201,122},{255,220,155},{255,238,197}}
local foam={{57,88,99},{70,103,111},{86,119,124},{105,137,139},{129,157,156},{157,181,177},{188,207,199},{224,234,222}}
local function clamp(v,a,b) if v<a then return a elseif v>b then return b else return v end end
local function mix(a,b,t) return floor(a+(b-a)*t+0.5) end
local function ramp(tab,q)
 q=clamp(q,0,0.999)*#tab
 local i=clamp(floor(q)+1,1,#tab)
 local j=min(#tab,i+1)
 local f=q-floor(q)
 return mix(tab[i][1],tab[j][1],f),mix(tab[i][2],tab[j][2],f),mix(tab[i][3],tab[j][3],f)
end
local function paintSky()
 for y=0,HY-1 do
  local r,g,b=ramp(sky,y/(HY-1))
  Line(0,y,127,y,r,g,b)
 end
end
paintSky()
local function swell(x,y,t)
 local d=(y-HY)/(64-HY)
 local v=sin(x*.073+t*tau*.32+y*.17)*.52
 v=v+sin(x*.131-t*tau*.21+y*.09+1.8)*.31
 v=v+sin(x*.027+t*tau*.13+y*.31+4.1)*.61
 return v*(.2+d*.9)
end
local function ocean(t)
 local sx=75+sin(t*tau*.43)*4
 for y=HY,63 do
  local d=(y-HY)/39
  local r,g,b=ramp(sea,d)
  Line(0,y,127,y,r,g,b)
  local bands=2+floor(d*2)
  for j=1,bands do
   local k=y*41+j*113
   local x=floor(B(k)*146)-9
   local len=2+floor(d*(4+B(k+1)*10))
   local yy=y+floor(swell(x,y,t))
   local lift=10+floor(30*d+18*B(k+2))
   Line(x,yy,x+len,yy,clamp(r+lift,0,255),clamp(g+lift,0,255),clamp(b+lift,0,255))
  end
 end
end
local function clouds(t)
 for i=0,72 do
  local k=2700+i*31
  local layer=floor(B(k+5)*4)
  local x=(B(k)*146+t*(74+layer*19))%150-11
  local y=3+B(k+1)*18+sin(t*tau*.18+B(k+4)*tau)*.45
  local len=2+floor(B(k+2)*12)
  local dusk=clamp((y-6)/17,0,1)
  local r=mix(67,238,dusk);local g=mix(81,137,dusk);local b=mix(119,143,dusk)
  local shade=.55+B(k+3)*.45
  r=floor(r*shade);g=floor(g*shade);b=floor(b*shade)
  Line(x-len,y,x+len,y,r,g,b)
  if B(k+7)>.48 then Line(x-len*.65,y-1,x+len*.48,y-1,r,g,b) end
  if B(k+8)>.78 then Blend(x,y+1,255,143,121,.18+B(k+9)*.2) end
 end
end
local function sun(t)
 local rise=.5-.5*cos(t*pi)
 local x=75-19*sin(t*pi)
 local y=24-rise*18
 local r=5+rise*2
 Glow(x,y,9+rise*7,255,111+rise*83,48+rise*105,.48+rise*.28)
 Circle(x,y,r,255,150+rise*74,67+rise*108,true)
 Line(x-r+1,y-1,x+r-1,y-1,255,200+rise*42,126+rise*91)
 return x,rise
end
local function glimmer(t,sx,rise)
 local reach=34-rise*17
 for i=0,62 do
  local k=6300+i*37
  local d=B(k+1)
  local y=HY+2+floor(d*d*reach)
  local width=2+d*(25-rise*9)
  local center=sx+(64-sx)*d+sin(t*tau*(.11+B(k+6)*.08)+B(k+2)*tau)*d*3
  local x=center+(B(k)*2-1)*width
  local pulse=.5+.5*sin(t*tau*(.42+B(k+4)*.38)+B(k+2)*tau)
  if pulse>.24 then
   local a=(pulse-.24)/.76*(.28+B(k+3)*.5)*(1+rise*.28)
   local c=warm[clamp(1+floor(a*8),1,8)]
   local len=1+floor(d*4+B(k+5)*3)
   Line(x-len,y,x+len,y,c[1],c[2],c[3])
   if a>.67 then Blend(x,y-1,255,239,194,a*.48) end
  end
 end
end
local function crests(t)
 for i=0,68 do
  local k=17100+i*43
  local d=B(k+1)
  local y=HY+3+floor(d*d*35)
  local x=(B(k)*142+t*(13+B(k+4)*16)+sin(t*tau*(.10+B(k+6)*.08)+B(k+2)*tau)*4*d)%142-7
  local w=.047+B(k+5)*.065
  local phase=sin(x*w+t*tau*(.22+B(k+4)*.28)+B(k+2)*tau+y*.16)
  local edge=.34-d*.10
  if phase>edge then
   local a=(phase-edge)/(1-edge)
   local c=foam[clamp(1+floor(a*8),1,8)]
   local len=1+floor((1+d*7)*a+B(k+3)*3)
   local yy=y+floor(swell(x,y,t)*.8)
   Line(x-len,yy,x+len,yy,c[1],c[2],c[3])
   if a>.74 and d>.3 then
    Pixel(x-len*.35,yy-1,202,221,212)
    if B(k+8)>.68 then Pixel(x+len*.45,yy-1,176,205,201) end
   end
  end
 end
end
local function ripples(t)
 for i=0,42 do
  local k=28900+i*29
  local d=B(k+1)
  local y=HY+1+floor(d*37)
  local x=(B(k)*128+t*(5+B(k+4)*9)+sin(t*tau*.14+B(k+2)*tau)*B(k+3)*5)%128
  local p=.5+.5*sin(t*tau*(.34+B(k+5)*.31)+B(k+2)*tau)
  if p>.28 then
   local r,g,b=ramp(sea,d)
   local q=18+floor(34*p*B(k+6))
   local len=1+floor(d*5)
   Line(x-len,y,x+len,y,clamp(r+q,0,255),clamp(g+q,0,255),clamp(b+q,0,255))
  end
 end
end
local function boat(x,y,s,flip,r,g,b)
 local d=flip and -1 or 1
 Line(x-s,y,x+s,y,20,24,29)
 Line(x-s+1,y+1,x+s-1,y+1,8,15,22)
 Line(x,y-1,x,y-s-3,32,34,37)
 Line(x,y-s-3,x+d*(s-1),y-2,r,g,b)
 Line(x+d*(s-1),y-2,x,y-2,r,g,b)
 Line(x-s*.55,y+3,x+s*.45,y+3,81,87,83)
end
local function boats(t)
 boat((t*39+7)%148-10,43,3,false,224,152,103)
 boat(137-(t*27%151),34,2,true,246,190,128)
 boat((t*21+71)%146-9,55,4,false,187,124,91)
end
local function gull(x,y,s,bank)
 local w=max(2,floor(s))
 local lift=floor(abs(bank)*2+.5)
 Line(x-w,y+lift,x,y,52,53,56)
 Line(x,y,x+w,y+lift,52,53,56)
 Pixel(x,y,27,29,33)
 if s>3 then
  Pixel(x-w,y+lift-1,136,125,116)
  Pixel(x+w,y+lift-1,136,125,116)
 end
end
local function gulls(t)
 local x=(t*177)%154-13
 gull(floor(x),floor(8+sin(t*tau*1.31)*2),4.5,sin(t*tau*2.07))
 local x2=140-(t*113%166)
 gull(floor(x2),floor(14+sin(t*tau*.79+2.3)*1.6),3,sin(t*tau*1.63+1))
end
local function clock()
 local n=px.now()
 local s=(n.hour<10 and "0" or "")..n.hour..":"..(n.min<10 and "0" or "")..n.min
 local w=px.width(s)
 Rect(125-w,54,w+3,9,4,12,19,true)
 Text(127-w,55,s,211,219,210)
end
function draw()
 F=F+1
 local t=px.t()
 paintSky()
 ocean(t)
 clouds(t)
 ripples(t)
 local sx,rise=sun(t)
 glimmer(t,sx,rise)
 crests(t)
 boats(t)
 gulls(t)
 clock()
end
